  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      hubspotAccessToken: 'test-hubspot-token',
      fetch
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeCheckoutSession, config);
    expect(calls.length).toBeGreaterThan(0);
