    const secret = 'whsec_test_secret';
    const payload = '{"id":"cs_test_123","customer_email":"customer@example.com"}';
    const timestamp = Math.floor(Date.now() / 1000 - 600).toString(); // 10 minutes ago
    const encoder = new TextEncoder();
    const keyData = encoder.encode(secret);
    const messageData = encoder.encode(`${timestamp}.${payload}`);
    const key = await crypto.subtle.importKey('raw', keyData, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const sigBuffer = await crypto.subtle.sign('HMAC', key, messageData);
    const signature = Array.from(new Uint8Array(sigBuffer))
