  fetch: typeof fetch;
  /** Raw request body as received from Stripe (for signature verification). */
  rawBody?: string;
  /** Value of the Stripe-Signature header (for signature verification). */
  stripeSignature?: string;
}

/** Stripe Checkout Session object as delivered in the checkout.session.completed webhook (data.object). */
export interface StripeCheckoutSession {
  id: string;
  object: 'checkout.session';
  customer_email: string;
  client_reference_id?: string | null;
  [key: string]: unknown;
}

/** HubSpot createOrUpdate response (v1 legacy). */
interface HubSpotContactResponse {
  vid: number;
  isNew: boolean;
}

/** Result returned by the connector. */
export interface HandleResult {
