/** Verify a Stripe webhook signature using HMAC-SHA256. */
async function verifyStripeSignature(
  secret: string,
  payload: string,
  signatureHeader: string
): Promise<void> {
  // Parse "t=timestamp,v1=signature"
  const parts = signatureHeader.split(',').map((s) => s.trim());
  let timestamp: string | undefined;
  let signature: string | undefined;
  for (const part of parts) {
    if (part.startsWith('t=')) timestamp = part.slice(2);
    else if (part.startsWith('v1=')) signature = part.slice(3);
  }
  if (!timestamp || !signature) {
    throw new Error('Invalid Stripe-Signature header format');
  }

  // Reject timestamps older than 5 minutes (300s)
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - parseInt(timestamp, 10)) > 300) {
    throw new Error('Stripe webhook timestamp too old');
  }

  const signedPayload = `${timestamp}.${payload}`;
  const encoder = new TextEncoder();
  const keyData = encoder.encode(secret);
  const messageData = encoder.encode(signedPayload);

  // Web Crypto API (available in Cloudflare Workers, Deno, Bun, Node 16+ with global crypto)
  const key = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const signatureBuffer = await crypto.subtle.sign('HMAC', key, messageData);
  const expectedSignature = Array.from(new Uint8Array(signatureBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');

  if (expectedSignature !== signature) {
    throw new Error('Invalid Stripe webhook signature');
  }
}

/**
 * Handle a Stripe checkout.session.completed webhook payload.
 * Creates or updates a HubSpot contact using the customer email.
 * Uses the Stripe session id as Idempotency-Key to prevent duplicates.
 */
export async function handle(
  payload: StripeCheckoutSession,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  if (!payload.customer_email) {
    throw new Error('Missing required field: customer_email');
  }
  if (!payload.id) {
    throw new Error('Missing required field: id');
  }

  // Verify webhook signature if secret and signature data are provided
  if (config.stripeWebhookSecret && config.rawBody && config.stripeSignature) {
    await verifyStripeSignature(config.stripeWebhookSecret, config.rawBody, config.stripeSignature);
  }

  // Prepare HubSpot request
  const contactEmail = encodeURIComponent(payload.customer_email);
  const url = `https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/${contactEmail}`;

  const properties: Array<{ property: string; value: string }> = [
    { property: 'email', value: payload.customer_email }
  ];

  // Include client_reference_id as a custom property if present
  if (payload.client_reference_id) {
    properties.push({ property: 'client_reference_id', value: payload.client_reference_id });
  }

  const body = JSON.stringify({ properties });

  const headers: Record<string, string> = {
    Authorization: `Bearer ${config.hubspotAccessToken}`,
    'Content-Type': 'application/json',
    'Idempotency-Key': payload.id
  };

  const response = await config.fetch(url, {
    method: 'POST',
    headers,
    body
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => 'Unknown error');
    throw new Error(
      `HubSpot API error (${response.status} ${response.statusText}) at ${url}: ${errorText}`
    );
  }

  const result = (await response.json()) as HubSpotContactResponse;

  return {
    hubspotContactId: result.vid,
    isNewContact: result.isNew,
    idempotencyKey: payload.id
  };
}

